#!/bin/bash
# up_cam_1113 — 11-13 §0: camera.launch.py(color_fps 인자 추가, 기본 15 = 그 전과 같음) 를 Jetson src 로 배포. 로버 안 움직임 · 빌드 안 함 · 노드 안 띄움.
#   하는 일: ① 백업 /tmp/deploy_backup_1113 ② 아래 base64(PC 저장소 판, CR 제거) 로 덮어씀(설치본은 src 링크) ③ md5 대조(PC 87af89ff04b8) ④ 설치본 링크 ⑤ --show-args 로 color_fps 기본값.
#   인자: 없음. 출력: 표준 출력.
set -e; S=~/ros2_ws/src/rover_bringup/launch/camera.launch.py; B=/tmp/deploy_backup_1113; mkdir -p $B; cp $S $B/
echo '' | base64 -d > $S
echo "== md5: cam $(md5sum < $S | cut -c1-12)(PC 87af89ff04b8)"
I=~/ros2_ws/install/rover_bringup/share/rover_bringup/launch/camera.launch.py; [ -L $I ] && echo "== 설치본 링크 -> $(readlink -f $I)" || echo "== ⚠ 설치본이 링크 아님"
ros2 launch rover_bringup camera.launch.py --show-args 2>&1 | grep -A2 "'color_fps'" | sed 's/^ */  /'
